<?php
use backend\models\AcademicActivity; use common\widgets\Alert; use kartik\date\DatePicker; use kartik\form\ActiveForm; use yii\helpers\ArrayHelper; use yii\helpers\Html; use yii\helpers\Url;
$activities = ArrayHelper::map(AcademicActivity::find()->orderBy('name')->all(), 'id', 'name');
?>
<?= Alert::widget() ?><div class="card card-primary card-outline mb-3"><div class="card-header"><h3 class="card-title mb-0"><?= $model->isNewRecord ? 'Form Tambah Kalender Akademik' : 'Form Ubah Kalender Akademik' ?></h3></div><?php $form = ActiveForm::begin(['id' => 'academic-calendar-form', 'options' => ['autocomplete' => 'off'], 'enableClientValidation' => true, 'validateOnChange' => true, 'validateOnSubmit' => true]); ?><div class="card-body"><div class="row"><div class="col-lg-6 col-md-6 col-12"><?= $form->field($model, 'period')->textInput(['maxlength' => true, 'placeholder' => 'Contoh: 2017/2018 Ganjil']) ?><?= $form->field($model, 'academic_activity_id')->dropDownList($activities, ['prompt' => '- Pilih Kegiatan -']) ?><?= $form->field($model, 'start_date')->widget(DatePicker::class, ['pluginOptions' => ['format' => 'yyyy-mm-dd', 'autoclose' => true]]) ?></div><div class="col-lg-6 col-md-6 col-12"><?= $form->field($model, 'end_date')->widget(DatePicker::class, ['pluginOptions' => ['format' => 'yyyy-mm-dd', 'autoclose' => true]]) ?><?= $form->field($model, 'description')->textarea(['rows' => 3, 'placeholder' => 'Keterangan kalender akademik']) ?><div class="d-flex"><?= $form->field($model, 'is_academic_holiday')->checkbox(['class' => 'mr-2']) ?><?= $form->field($model, 'is_national_holiday')->checkbox(['class' => 'ml-4 mr-2']) ?></div></div></div></div><div class="card-footer d-flex"><?php if (!$model->isNewRecord): ?><?= Html::a('<i class="fas fa-fw fa-arrow-left"></i><span> Kembali</span>', Url::to(['index']), ['class' => 'btn btn-sm btn-default']) ?><?php endif; ?><div class="ml-auto" id="action-right"><?= Html::a('<i class="fas fa-fw fa-arrow-left"></i><span> Batal</span>', $model->isNewRecord ? Url::to(['index']) : Url::to(['view', 'id' => $model->id]), ['class' => 'btn btn-sm btn-secondary mr-1']) ?><?= Html::submitButton('<i class="fas fa-fw fa-check"></i><span> ' . ($model->isNewRecord ? 'Simpan' : 'Ubah') . '</span>', ['class' => 'btn btn-sm btn-' . ($model->isNewRecord ? 'success' : 'warning')]) ?></div></div><?php ActiveForm::end(); ?></div>
